    public PayrollItem testCreate() throws Throwable {
    PayrollItem entity = null;

    LOGGER.info( "PayrollItemTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a PayrollItem");

    StringBuilder msg = new StringBuilder( "-- Failed to create a PayrollItem" );

    try {
        entity = service.createPayrollItem( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getPayrollItemId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a PayrollItem with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

