    /**
     * Tests getting all PayrollItems.
     *
     * @return    Collection
     */
    public List<PayrollItem> testGetAll() throws Throwable {
    LOGGER.info( "PayrollItemTest:testGetAll() - Retrieving Collection of PayrollItems:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all PayrollItem : " );
    List<PayrollItem> collection  = null;

    try {
        // call the static get method on the PayrollItemService
        collection = service.getAllPayrollItem();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            PayrollItem currEntity  = null;
            Iterator<PayrollItem> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getPayrollItemId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

